const hasAgent=(scope:PolicyScope)=>['agent_tool','agent_all','team_agent_tool','user_agent_tool'].includes(scope);
const hasTool=(scope:PolicyScope)=>!['agent_all','team_all','user_all'].includes(scope);
const hasUser=(scope:PolicyScope)=>['user_tool','user_agent_tool','user_all'].includes(scope);
const hasTeam=(scope:PolicyScope)=>['team_tool','team_agent_tool','team_all'].includes(scope);
function scopeKey(t:PolicyTarget):string{return ['scope',t.scope,hasAgent(t.scope)?t.agentId:'',hasTool(t.scope)?t.toolId:'',hasUser(t.scope)?t.userId:'',hasTeam(t.scope)?t.team:''].join('|')}
