// Restrict reverse conversion to a lossless subset; advanced CEL remains editable only in raw mode.
function celToClauses(expression:string,attrs:AttributeDef[]):ConditionPolicy|null{
 const compiled=compileCel(expression,attrs);if(!compiled.ok||!compiled.ast)return null;if(compiled.ast.tag==='literal'&&compiled.ast.value===true)return {mode:'all',clauses:[],editor:'visual'};
 const pieces:CelNode[]=[];let join:string='';
 const split=(n:CelNode):boolean=>{if(n.tag==='binary'&&(n.op==='&&'||n.op==='||')){
   if(join&&join!==n.op)return false;join=n.op;return split(n.left!)&&split(n.right!);
  }pieces.push(n);return true};
 if(!split(compiled.ast))return null;
 const clauses:PolicyClause[]=[];
 for(const n of pieces){let field:CelNode|undefined,value:CelNode|undefined,operator:string='';
  if(n.tag==='binary'&&['==','!=','>','>=','<','<='].includes(n.op!)){field=n.left;value=n.right;operator=({'==':'eq','!=':'neq','>':'gt','>=':'gte','<':'lt','<=':'lte'} as any)[n.op!];}
  else if(n.tag==='method'&&n.op==='contains'){field=n.left;value=n.right;operator='contains';}
  else if(n.tag==='unary'&&n.left?.tag==='method'&&n.left.op==='contains'){field=n.left.left;value=n.left.right;operator='notcontains';}
  else return null;
  if(field?.tag!=='var'||value?.tag!=='literal')return null;
  const attr=attrs.find(a=>celVar(a)===field!.value);
  if(!attr||!permittedOperators(attr.kind).some(o=>o.id===operator))return null;
  const valueString=String(value!.value);
  clauses.push({id:'raw-to-visual-'+clauses.length,attrId:attr.id,operator,value:valueString});
 }
 return {mode:join==='||'?'any':'all',clauses,editor:'visual'};
}
function policyCel(p:ConditionPolicy,attrs:AttributeDef[]):string{return p.editor==='raw'?p.raw||'':clausesToCel(p,attrs)}
function checkPolicy(p:ConditionPolicy|null,attrs:AttributeDef[]){return p?compileCel(policyCel(p,attrs),attrs):compileCel('true',attrs)}

