function readCache(){try{return JSON.parse(localStorage.getItem(lsKey)||localStorage.getItem(oldLsKey)||'null')}catch(e){return null}}
function storeCache(data:any){try{localStorage.setItem(lsKey,JSON.stringify(data))}catch(e){}}
function nice(t:string){return t.replace(/_/g,' ').replace(/\./g,' / ')}
function initials(s:string){return s.split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase()}
function plural(n:number,singular:string,pluralName:string){return n+' '+(n===1?singular:pluralName)}
function classNames(...v:any[]){return v.filter(Boolean).join(' ')}

